def field_annotations(typed_dict) -> Tuple[Dict[str, type], Dict[str, type]]:
    """Return the required and optional fields in the TypedDict."""
    return (
        typed_dict.__annotations__["required_fields"].__annotations__,
        typed_dict.__annotations__["optional_fields"].__annotations__,
    )

def make_typed_dict(*, required_fields=None, optional_fields=None) ->type:
    if required_fields is None:
        required_fields = {}
    if optional_fields is None:
        optional_fields = {}

    # Create TypedDict for required fields
    required_td = TypedDict(DUMMY_REQUIRED_TYPED_DICT_NAME, required_fields, total=True)

    # Create TypedDict for optional fields
    optional_td = TypedDict(DUMMY_OPTIONAL_TYPED_DICT_NAME, optional_fields, total=False)

    # Create the main TypedDict with required_fields and optional_fields as annotations
    main_td = TypedDict(
        DUMMY_TYPED_DICT_NAME,
        {"required_fields": required_td, "optional_fields": optional_td},
        total=True
    )

    return main_td
